//! Per-module data of the Beathoven Synthesizer replayer, written out from the specification's
//! tables (`bss-subsongs.tsv`, `bss-patches.tsv`); numeric data and the sample-pointer fix-ups
//! the originals' start-up routines make, not original code.

/// One subsong of one build. `longs` and `ins` (the header long at hunk offset 0x30) name the build.
/// `eng`: 0 request-block engine ("100"), 1 register-direct ("109"), 2 its older simple variant,
/// 3 the "NEW" builds. `lists` are the voices' (list, loop) hunk offsets; `d7` the engine 100's
/// per-voice note offsets; `patch` the (hunk offset, bytes) writes made before the first tick.
pub struct Row {
    pub longs: u32,
    pub ins: u32,
    pub sub: u8,
    pub eng: u8,
    pub voices: u8,
    pub voice3: bool,
    pub m: u16,
    pub n: u16,
    pub k5: bool,
    pub table: u32,
    pub silent: u32,
    pub silent_abs: bool,
    pub cmd85: bool,
    pub signed: bool,
    pub lists: [u32; 8],
    pub d7: [i32; 4],
    pub prologue: bool,
    pub post_reset: bool,
    pub init_dma: bool,
    pub patch: &'static [(u32, &'static [u8])],
}

